  class ContextChunker { private int $maxTokens; public function __construct(int $maxTokens = 12000) { $this->maxTokens = $maxTokens; } public function estimateTokens(string $text): int { return (int) ceil(strlen($text) / 4); } public function selectAndChunkFiles(array $rankedFiles, string $basePath): array { $selectedFiles = []; $currentTokens = 0; $truncatedNotice = false; foreach ($rankedFiles as $relativePath => $info) { $fullPath = $info['full_path'] ?? ($basePath . '/' . $relativePath); if (!file_exists($fullPath) || !is_readable($fullPath)) { continue; } $content = file_get_contents($fullPath) ?: ''; $fileTokens = $this->estimateTokens($content); if ($currentTokens + $fileTokens > $this->maxTokens) { if ($info['score'] >= 15 && $currentTokens < $this->maxTokens) { $allowedChars = ($this->maxTokens - $currentTokens) * 4; $content = substr($content, 0, $allowedChars) . "\n// [TRUNCATED: Context limit reached]"; $selectedFiles[$relativePath] = [ 'path' => $relativePath, 'content' => $content, 'score' => $info['score'], 'truncated' => true ]; } $truncatedNotice = true; break; } $selectedFiles[$relativePath] = [ 'path' => $relativePath, 'content' => $content, 'score' => $info['score'], 'truncated' => false ]; $currentTokens += $fileTokens; } return [ 'files' => $selectedFiles, 'total_tokens' => $currentTokens, 'max_tokens' => $this->maxTokens, 'truncated' => $truncatedNotice ]; } } 